+                              FLUX_PLUGIN_ARG_OUT|FLUX_PLUGIN_ARG_UPDATE,
+                              "{s:s}",
+                              "errmsg", errmsg) < 0) {
+        flux_t *h = flux_jobtap_get_flux (p);
+        if (h)
+            flux_log_error (h, "flux_jobtap_reject_job: failed to pack error");
+    }
+    return -1;
+}
